/**
 * Generated by `createservice news.GetNewsItemsRecipientsCountersService --type mutations`
 */
const filter = require('lodash/filter')
const get = require('lodash/get')
const pick = require('lodash/pick')
const uniq = require('lodash/uniq')
const uniqBy = require('lodash/uniqBy')

const { GQLError, GQLErrorCode: { BAD_USER_INPUT } } = require('@open-condo/keystone/errors')
const { GQLCustomSchema, allItemsQueryByChunks } = require('@open-condo/keystone/schema')

const access = require('@condo/domains/news/access/GetNewsItemsRecipientsCountersService')
const {
    countUniqueUnitsFromResidentsByPropertyIds,
    countUniqueUnitsFromResidentsByProperty,
    getUnitsFromProperty,
} = require('@condo/domains/news/utils/serverSchema/recipientsCounterUtils')



const CHUNK_SIZE = 50

const ERRORS = {
    SCOPE_NOT_SUPPORTED: {
        code: BAD_USER_INPUT,
        type: 'SCOPE_NOT_SUPPORTED',
        message: 'Cannot count recipients on these scopes. Only: Organization-level scope, Property-level scope, or UnitName/UnitType level scopes are supported',
    },
}

/**
 * @param {string} organizationId
 * @param {object} property
 * @param {{ unitType: string?, unitName: string? }[]} propertyUnitsFromScope
 * @returns {Promise<{ unitsCount: number, receiversCount: number }>}
 */
async function countUnitLevelRecipientsForProperty (organizationId, property, propertyUnitsFromScope) {
    const unitsFromProperty = getUnitsFromProperty(property)
    const scopesUnitNamesByUnitType = {}
    const typeWideByUnitType = {}
    let unitsCount = 0
    let receiversCount = 0

    for (const unitFilter of propertyUnitsFromScope) {
        if (!unitFilter.unitName && unitFilter.unitType) {
            typeWideByUnitType[unitFilter.unitType] = true
        }
    }

    for (const unitType of Object.keys(typeWideByUnitType)) {
        unitsCount += filter(unitsFromProperty, { unitType }).length
    }

    for (const unitFilter of propertyUnitsFromScope) {
        if (!unitFilter.unitName) continue
        if (typeWideByUnitType[unitFilter.unitType]) continue

        if (!scopesUnitNamesByUnitType[unitFilter.unitType]) {
            scopesUnitNamesByUnitType[unitFilter.unitType] = []
        }
        scopesUnitNamesByUnitType[unitFilter.unitType].push(unitFilter.unitName)

        unitsCount += filter(unitsFromProperty, unitFilter).length
    }

    if (Object.keys(scopesUnitNamesByUnitType).length > 0) {
        const unitLevelResidentsCount = Number(await countUniqueUnitsFromResidentsByProperty(
            organizationId,
            property.id,
            scopesUnitNamesByUnitType,
        )) || 0
        receiversCount += unitLevelResidentsCount
    }

    const typeWideUnitTypes = Object.keys(typeWideByUnitType)
    if (typeWideUnitTypes.length > 0) {
        const uniqueTypeWideUnits = new Set()

        await allItemsQueryByChunks({
            schemaName: 'Resident',
            chunkSize: CHUNK_SIZE,
            where: {
                organization: { id: organizationId },
                property: { id: property.id },
                unitType_in: typeWideUnitTypes,
                deletedAt: null,
            },
            /**
             * @param {Resident[]} chunk
             * @returns {Resident[]}
             */
            chunkProcessor: (chunk) => {
                for (const resident of chunk) {
                    uniqueTypeWideUnits.add(`${resident.unitType}:${resident.unitName}`)
                }

                return []
            },
        })

        receiversCount += uniqueTypeWideUnits.size
    }

    return { unitsCount, receiversCount }
}

/**
 * @param {object[]} newsItemScopes
 * @param {string} organizationId
 * @returns {Promise<{ propertiesCount: number, unitsCount: number, receiversCount: number } | null>}
 */
async function countUnitLevelRecipients (newsItemScopes, organizationId) {
    const allHaveProperty = newsItemScopes.every(scope => get(scope, ['property', 'id']))

    if (!allHaveProperty) {
        return null
    }

    /**
     * @type {Object<string, {unitType: string?, unitName: string?}[]>}
     */
    const scopesUnitsByProperties = newsItemScopes.reduce((acc, scope) => {
        const propertyId = scope.property.id
        return {
            ...acc,
            [propertyId]: uniqBy([
                ...(acc[propertyId] || []),
                pick(scope, ['unitName', 'unitType']),
            ], ({ unitName, unitType }) => `${unitType}:${unitName}`),
        }
    }, {})

    const propertyIds = Object.keys(scopesUnitsByProperties)
    const properties = []
    let propertiesCount = 0
    let unitsCount = 0
    let receiversCount = 0

    await allItemsQueryByChunks({
        schemaName: 'Property',
        chunkSize: CHUNK_SIZE,
        where: { id_in: propertyIds, deletedAt: null },
        /**
         * @param {Property[]} chunk
         * @returns {Property[]}
         */
        chunkProcessor: (chunk) => {
            propertiesCount += chunk.length
            properties.push(...chunk)

            return []
        },
    })

    for (const property of properties) {
        const propertyCounters = await countUnitLevelRecipientsForProperty(
            organizationId,
            property,
            scopesUnitsByProperties[property.id],
        )
        unitsCount += propertyCounters.unitsCount
        receiversCount += Number(propertyCounters.receiversCount) || 0
    }

    return { propertiesCount, unitsCount, receiversCount }
}


const GetNewsItemsRecipientsCountersService = new GQLCustomSchema('GetNewsItemsRecipientsCountersService', {
    types: [
        {
            access: true,
            type: 'input GetNewsItemsRecipientsCountersInput { dv: Int!, sender: JSON!, organization: OrganizationWhereUniqueInput!, newsItemScopes: [NewsItemScopeWhereInput!]! }',
        },
        {
            access: true,
            type: 'type GetNewsItemsRecipientsCountersOutput { propertiesCount: Int!, unitsCount: Int!, receiversCount: Int! }',
        },
    ],

    queries: [
        {
            access: access.canGetNewsItemsRecipientsCounters,
            schema: 'getNewsItemsRecipientsCounters(data: GetNewsItemsRecipientsCountersInput!): GetNewsItemsRecipientsCountersOutput',
            resolver: async (parent, args, context) => {
                const { data: { newsItemScopes, organization: { id: organizationId } } } = args

                // todo (DOMA-10129) move to addressKey in scopes + finish rebuilding this query
                let propertiesCount = 0, unitsCount = 0, receiversCount = 0


                // Organization level scope
                const isAllOrganization = filter(newsItemScopes, {
                    property: null,
                    unitType: null,
                    unitName: null,
                }).length > 0

                if (isAllOrganization) {
                    const propertyIds = []

                    await allItemsQueryByChunks({
                        schemaName: 'Property',
                        chunkSize: CHUNK_SIZE,
                        where: { organization: { id: organizationId }, deletedAt: null },
                        /**
                         * @param {Property[]} chunk
                         * @returns {Property[]}
                         */
                        chunkProcessor: (chunk) => {
                            propertiesCount += chunk.length
                            for (const property of chunk) {
                                unitsCount += (property.unitsCount + property.uninhabitedUnitsCount)
                                propertyIds.push(property.id)
                            }

                            return []
                        },
                    })

                    receiversCount = await countUniqueUnitsFromResidentsByPropertyIds(organizationId, propertyIds)

                    return { propertiesCount, unitsCount, receiversCount }
                }


                // Property level scopes only
                const isByProperties = filter(newsItemScopes, {
                    unitType: null,
                    unitName: null,
                }).length >= newsItemScopes.length

                if (isByProperties) {
                    const scopesByProperty = filter(newsItemScopes, {
                        unitType: null,
                        unitName: null,
                    })

                    const scopesByPropertyPropertyIds = uniq(scopesByProperty.map(({ property: { id } }) => id))

                    await allItemsQueryByChunks({
                        schemaName: 'Property',
                        chunkSize: CHUNK_SIZE,
                        where: { id_in: scopesByPropertyPropertyIds, deletedAt: null },
                        /**
                         * @param {Property[]} chunk
                         * @returns {Property[]}
                         */
                        chunkProcessor: (chunk) => {
                            propertiesCount += chunk.length
                            for (const property of chunk) {
                                unitsCount += (property.unitsCount + property.uninhabitedUnitsCount)
                            }

                            return []
                        },
                    })

                    receiversCount = await countUniqueUnitsFromResidentsByPropertyIds(organizationId, scopesByPropertyPropertyIds)

                    return { propertiesCount, unitsCount, receiversCount }
                }

                const unitLevelCounters = await countUnitLevelRecipients(newsItemScopes, organizationId)
                if (unitLevelCounters) {
                    return unitLevelCounters
                }

                throw new GQLError(ERRORS.SCOPE_NOT_SUPPORTED, context)
            },
        },
    ],

})

module.exports = {
    GetNewsItemsRecipientsCountersService,
}
